(function(){'use strict';function normalizeTabId(tabId){if(!tabId)return'doc-overview';var t=String(tabId).trim();if(t==='feedback'||t==='doc-feedback'||t==='patient-review'||t==='reviews'){return'doc-patient-review'}
if(t==='notifications'||t==='doc-notifications'){return'doc-notifications-system'}
if(t==='documents'||t==='doc-documents'){return'doc-documents-upload'}
if(t==='patients'||t==='doc-patients'){return'doc-patients-all'}
if(t==='appointments'){return'doc-appointments'}
if(t==='settings'){return'doc-settings'}
return t}
window.diorToggleSubmenu=function(e,menuId){if(e&&e.preventDefault)e.preventDefault();var targetMenu=document.getElementById(menuId);if(!targetMenu)return;var isAlreadyOpen=targetMenu.classList.contains('active')||targetMenu.classList.contains('open');document.querySelectorAll('#dior-doc-sidebar .dior-nav-item.has-submenu').forEach(function(item){if(item.id!==menuId){item.classList.remove('active','open');var icon=item.querySelector('.submenu-icon');if(icon){icon.classList.remove('fa-minus');icon.classList.add('fa-plus')}}});if(isAlreadyOpen){targetMenu.classList.remove('active','open');var icon=targetMenu.querySelector('.submenu-icon');if(icon){icon.classList.remove('fa-minus');icon.classList.add('fa-plus')}}else{targetMenu.classList.add('active','open');var icon=targetMenu.querySelector('.submenu-icon');if(icon){icon.classList.remove('fa-plus');icon.classList.add('fa-minus')}}};window.diorDocCloseMobile=function(){var sidebar=document.getElementById('dior-doc-sidebar');var backdrop=document.getElementById('dior-doc-backdrop');if(sidebar)sidebar.classList.remove('mobile-open');if(backdrop)backdrop.classList.remove('active')};window.diorDocOpenMobile=function(){var sidebar=document.getElementById('dior-doc-sidebar');var backdrop=document.getElementById('dior-doc-backdrop');if(!sidebar)return;var isOpen=sidebar.classList.contains('mobile-open');if(isOpen){sidebar.classList.remove('mobile-open');if(backdrop)backdrop.classList.remove('active')}else{sidebar.classList.add('mobile-open');if(backdrop)backdrop.classList.add('active')}};window.diorDocSwitchTab=function(tabId,updateUrl){var app=document.getElementById('dior-doctor-app');if(!tabId)return!1;var normalizedId=normalizeTabId(tabId);var contentRoot=app?app.querySelector('#dior-doc-content'):document.getElementById('dior-doc-content');var activePanel=contentRoot?contentRoot.querySelector('#tab-'+normalizedId):null;if(!activePanel&&contentRoot){activePanel=contentRoot.querySelector('#'+normalizedId)}
if(!activePanel&&contentRoot&&normalizedId!=='doc-overview'){activePanel=contentRoot.querySelector('#tab-doc-overview');normalizedId='doc-overview'}
if(!activePanel){console.warn('[Dior Navigation] Panel not found for tab:',tabId,'(normalized: '+normalizedId+')');return!1}
var notifDropdown=document.getElementById('dior-doc-notif-dd');if(notifDropdown){notifDropdown.classList.remove('open','active')}
var sidebar=app?app.querySelector('#dior-doc-sidebar'):document.getElementById('dior-doc-sidebar');var buttons=sidebar?sidebar.querySelectorAll('.dior-nav-btn'):[];buttons.forEach(function(b){b.classList.remove('active')});var activeBtn=sidebar?sidebar.querySelector('.dior-nav-btn[data-tab="'+normalizedId+'"]'):null;if(activeBtn){activeBtn.classList.add('active');var parentSubmenu=activeBtn.closest('.dior-nav-item.has-submenu');document.querySelectorAll('#dior-doc-sidebar .dior-nav-item.has-submenu').forEach(function(sub){if(parentSubmenu&&sub===parentSubmenu){sub.classList.add('active','open');var subIcon=sub.querySelector('.submenu-icon');if(subIcon){subIcon.classList.remove('fa-plus');subIcon.classList.add('fa-minus')}}else{sub.classList.remove('active','open');var subIcon=sub.querySelector('.submenu-icon');if(subIcon){subIcon.classList.remove('fa-minus');subIcon.classList.add('fa-plus')}}});var badge=activeBtn.querySelector('.nav-count-badge');if(badge){badge.style.transition='opacity 0.25s ease, transform 0.25s ease';badge.style.opacity='0';badge.style.transform='scale(0.5)';setTimeout(function(){badge.style.display='none'},250)}}
var panels=contentRoot?contentRoot.querySelectorAll(':scope > .dior-tab-panel'):[];panels.forEach(function(panel){if(panel===activePanel){panel.classList.add('active');panel.removeAttribute('hidden');panel.style.removeProperty('display');panel.style.display='block'}else{panel.classList.remove('active');panel.setAttribute('hidden','hidden');panel.style.display='none'}});if(updateUrl!==!1&&window.history&&window.history.replaceState){try{window.history.replaceState(null,'','#tab='+encodeURIComponent(normalizedId))}catch(e){}}
if(window.diorDoctorInitTablePagination){activePanel.querySelectorAll('.dior-doc-table, .dior-table, .dior-clean-table').forEach(function(table){if(table._diorRenderPage){table._diorRenderPage(1)}else{window.diorDoctorInitTablePagination(table,5)}})}
if(normalizedId==='doc-appointments'&&typeof window.diorRenderDoctorCalendar==='function'){setTimeout(window.diorRenderDoctorCalendar,40)}
window.diorDocCloseMobile();return!0};function boot(){var app=document.getElementById('dior-doctor-app');if(!app||app.__diorDoctorNavigationReady)return;app.__diorDoctorNavigationReady=!0;app.addEventListener('click',function(event){var tabBtn=event.target.closest('#dior-doctor-app #dior-doc-sidebar .dior-nav-btn[data-tab]');if(tabBtn){var tab=tabBtn.getAttribute('data-tab');if(tab){event.preventDefault();window.diorDocSwitchTab(tab,!0);return}}
var parentMenuBtn=event.target.closest('#dior-doctor-app #dior-doc-sidebar .dior-nav-item.has-submenu > .dior-nav-btn');if(parentMenuBtn&&!parentMenuBtn.getAttribute('data-tab')){var parentItem=parentMenuBtn.closest('.dior-nav-item.has-submenu');if(parentItem&&parentItem.id){event.preventDefault();window.diorToggleSubmenu(event,parentItem.id);return}}},!0);function syncTabFromUrl(updateUrl){var hashMatch=window.location.hash.match(/^#tab=([^&]+)/);var requestedTab='doc-overview';if(hashMatch){try{requestedTab=decodeURIComponent(hashMatch[1])}catch(error){requestedTab='doc-overview'}}
requestedTab=normalizeTabId(requestedTab);var app=document.getElementById('dior-doctor-app');var contentRoot=app?app.querySelector('#dior-doc-content'):document.getElementById('dior-doc-content');var panel=contentRoot?contentRoot.querySelector('#tab-'+requestedTab):null;var tabToLoad=panel?requestedTab:'doc-overview';window.diorDocSwitchTab(tabToLoad,updateUrl)}
window.addEventListener('hashchange',function(){syncTabFromUrl(!1)});syncTabFromUrl(!1)}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',boot,{once:!0})}else{boot()}})()